// Des: Tests the dispatcher: job classes, areas, re-login, dry run
// Flo: rowAt classes > expired page with no secrets = NeedLogin > with secrets = one automatic login then the job runs > dry run of a class H job does not wait
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-jobs-disp-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const disp = @import("ru-jobs-disp.zig"); const cas = @import("te-jobs-case.zig"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig");
fn rowOf(name: []const u8) ?disp.Row { var ix: usize = 0; while (ix < disp.rowCount()) : (ix += 1) { const rw = disp.rowAt(ix); if (std.mem.eql(u8, rw.name, name)) return rw; } return null; }
test "every row has a class: reversible = A, irreversible = G, stops for the owner = H" { try std.testing.expectEqual(@as(u8, 'A'), rowOf("post").?.cls); try std.testing.expectEqual(@as(u8, 'G'), rowOf("friend").?.cls); try std.testing.expectEqual(@as(u8, 'G'), rowOf("post-delete").?.cls); try std.testing.expectEqual(@as(u8, 'H'), rowOf("acct-login").?.cls); try std.testing.expectEqual(@as(u8, 'H'), rowOf("acct-delete").?.cls); try std.testing.expectEqual(@as(u8, 'H'), rowOf("mone-ads-create").?.cls); try std.testing.expectEqual(@as(u8, 'G'), rowOf("acct-pass-change").?.cls); try std.testing.expectEqualStrings("acct", rowOf("acct-login").?.area); try std.testing.expectEqualStrings("core", rowOf("post").?.area); var cnt = [_]u32{ 0, 0, 0 }; var ix: usize = 0; while (ix < disp.rowCount()) : (ix += 1) { switch (disp.rowAt(ix).cls) { 'A' => cnt[0] += 1, 'G' => cnt[1] += 1, 'H' => cnt[2] += 1, else => return error.TestUnexpectedResult } } try std.testing.expect(cnt[0] > 40 and cnt[1] > 40 and cnt[2] >= 15); }
test "every class H row has a hand step and a guard: needs approval or a login-type job; every spend row is on the mone cap" { for (&jobs.JOBS) |*jb| { const cls = jobs.classOf(jb); var hand = false; for (jb.steps) |tpl| { if (tpl.op == .hand) hand = true; } try std.testing.expectEqual(cls == 'H', hand); if (cls == 'H' and jb.risk == .w) try std.testing.expect(std.mem.eql(u8, jb.name, "acct-login")); if (jb.spend) try std.testing.expect(jb.kind == .mone and jb.risk == .x); if (jb.kind == .mone and std.mem.indexOf(u8, jb.name, "ads-pause") == null) try std.testing.expect(jb.risk == .x or jb.steps.len == 2); } }
test "an expired session: no secrets = NeedLogin; with secrets fb logs in once and the job then runs" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); cas.prep(&rig); var c1 = cas.mk(&rig, .live, ""); c1.secr = .{}; try std.testing.expectError(error.NeedLogin, disp.exec(&c1, "post-save", .{ .url = "/expire/1" })); try std.testing.expect(!rig.hasRec("btn|Log in|")); var c2 = cas.mk(&rig, .live, ""); try disp.exec(&c2, "post-save", .{ .url = "/expire/1" }); try std.testing.expect(rig.waitPre("btn|Log in|", 4000)); try std.testing.expect(rig.waitPre("btn|Save post|", 4000)); try std.testing.expect(c2.relog); }
test "a dry run of a class H job previews and never waits for the owner" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); cas.prep(&rig); var cx = cas.mk(&rig, .dry, ""); try disp.exec(&cx, "mone-paymethod-add", .{}); try std.testing.expect(std.mem.find(u8, rig.sink.items, "dry-run") != null); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
